def calc(expr: str) -> int | str:
    class _CalcError(Exception):
        pass

    n = len(expr)
    i = 0

    def skip_spaces() -> None:
        nonlocal i
        while i < n and expr[i].isspace():
            i += 1

    def parse_int() -> int:
        nonlocal i
        start = i
        while i < n and expr[i].isdigit():
            i += 1
        if i - start <= 4000:
            return int(expr[start:i])
        val = 0
        for j in range(start, i, 1000):
            chunk = expr[j : min(j + 1000, i)]
            val = val * (10 ** len(chunk)) + int(chunk)
        return val

    def parse_primary() -> int:
        nonlocal i
        skip_spaces()
        if expr[i] == "(":
            i += 1
            val = parse_expr()
            skip_spaces()
            i += 1
            return val
        return parse_int()

    def parse_unary() -> int:
        nonlocal i
        stack = []
        while True:
            skip_spaces()
            neg = 0
            while i < n and expr[i] == "-":
                neg += 1
                i += 1
                skip_spaces()
            val = parse_primary()
            stack.append((neg, val))
            skip_spaces()
            if i < n and expr[i] == "^":
                i += 1
            else:
                break

        neg, res = stack.pop()
        if neg & 1:
            res = -res
        while stack:
            neg, base = stack.pop()
            if res < 0:
                raise _CalcError
            res = base ** res
            if neg & 1:
                res = -res
        return res

    def parse_term() -> int:
        nonlocal i
        val = parse_unary()
        while True:
            skip_spaces()
            if i >= n:
                break
            op = expr[i]
            if op == "*":
                i += 1
                val *= parse_unary()
            elif op == "/" or op == "%":
                i += 1
                rhs = parse_unary()
                if rhs == 0:
                    raise _CalcError
                q = abs(val) // abs(rhs)
                if (val < 0) != (rhs < 0):
                    q = -q
                if op == "/":
                    val = q
                else:
                    val = val - rhs * q
            else:
                break
        return val

    def parse_expr() -> int:
        nonlocal i
        val = parse_term()
        while True:
            skip_spaces()
            if i >= n:
                break
            op = expr[i]
            if op == "+":
                i += 1
                val += parse_term()
            elif op == "-":
                i += 1
                val -= parse_term()
            else:
                break
        return val

    try:
        return parse_expr()
    except _CalcError:
        return "error"
